// ===== p194 : quatre boucles de maloya jouées par Paris dans Kontakt =====
// Rythmes de la librairie « Maloya Roots Percussions » (Wayo Audio), mixés ensemble en une prise par formation :
// kabaré (7 instruments), kasse (5), malbar binaire (5), maligasse (5). Boucles de 12 ou 16 s, mono 64 kb/s.
// Licence Wayo : les sons ne sont pas redistribuables isolément ; ici ce sont des mixages complets, intégrés au jeu.
Object.assign(SON193,{"boucle_kabare": "", "boucle_kasse": "", "boucle_malbar": "", "boucle_maligasse": ""});
const BCL194={kabare:12,kasse:16,malbar:16,maligasse:12};
function boucle194(ctx,dest,nom,v){try{const B=sons193(ctx),b=B&&B['boucle_'+nom];if(!b)return null;const s=ctx.createBufferSource();s.buffer=b;s.loop=true;s.loopStart=0;s.loopEnd=Math.min(b.duration,BCL194[nom]||b.duration);
 const g=ctx.createGain();g.gain.value=0;g.gain.setTargetAtTime(v,ctx.currentTime,.4);s.connect(g);g.connect(dest);s.start();
 return {nom,stop(){try{g.gain.setTargetAtTime(0,ctx.currentTime,.5);s.stop(ctx.currentTime+2.5)}catch(e){}}}}catch(e){return null}}
// dans l'île : le kabar (kabaré ou maligasse), le duel de moringue (kasse), les fêtes tamoules (malbar)
try{if(typeof PRE72!=='undefined'&&typeof SONCH!=='undefined'){let cur=null,curK='';
 const def=(k,choix)=>{const o={d:3.6,f:()=>{const c=typeof sndPret==='function'&&sndPret();if(!c)return;
   if(cur&&curK===k){o.d=3600;return}if(cur){cur.stop();cur=null}const nom=choix();cur=boucle194(c,SND.out,nom,.6);
   if(cur){curK=k;o.d=3600}else{o.d=3.6;if(PRE72.maloya68)PRE72.maloya68.f()}}};PRE72[k]=o};
 def('bclKabar',()=>Math.random()<.5?'kabare':'maligasse');def('bclKasse',()=>'kasse');def('bclMalbar',()=>'malbar');
 SONCH.kabar='bclKabar';SONCH.jDuel='bclKasse';SONCH.malbar='bclMalbar';
 setInterval(()=>{try{if(cur&&SONCH[SND.ambK]!==curK){cur.stop();cur=null;curK=''}}catch(e){}},300);
 SND.malbarJ=0;
 if(typeof momentCourant==='function'){const mc=momentCourant;momentCourant=function(){try{if(performance.now()<SND.malbarJ&&!(SND.jeu&&window.BTUON)&&!(typeof CINE!=='undefined'&&CINE))return 'malbar'}catch(e){}return mc.apply(this,arguments)}}
 if(typeof modal==='function'){const md=modal;modal=function(){try{if(S&&S.evq&&S.evq.length){const e=EV[S.evq[0]]||{},tx=((e.t||'')+' '+(typeof e.b==='string'?e.b:'')).toLowerCase();
   if(/malbar|tamoul|tamij|marche sur le feu|pandal|kavadi|pongal|kovil/.test(tx))SND.malbarJ=performance.now()+16000}}catch(e){}return md.apply(this,arguments)}}
}}catch(e){}
try{CRED144.push(["Boucles de maloya (kabaré, kasse, malbar, maligasse) : rythmes de la librairie « Maloya Roots Percussions », Wayo Audio, joués et mixés par Paris","Wayo Audio"])}catch(e){}
